const storage = {read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}},write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('Browser storage is unavailable. Changes last for this session.');return false;}}};
let savedRaw=storage.read('gather-saved',[]),ticketRaw=storage.read('gather-tickets',[]);
let saved=Array.isArray(savedRaw)?savedRaw.filter(id=>events.some(e=>e.id===id)):[];
let tickets=Array.isArray(ticketRaw)?ticketRaw.filter(t=>t&&typeof t.name==='string'&&typeof t.email==='string'&&typeof t.code==='string'&&events.some(e=>e.id===t.eventId)):[];
let category='All', savedOnly=false, selectedEvent=null, toastTimer;
const escapeHtml = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateFormat=new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'});
const timeFormat=new Intl.DateTimeFormat('en-IN',{hour:'numeric',minute:'2-digit',timeZone:'Asia/Kolkata'});
const dateText=e=>dateFormat.format(new Date(e.date));
const priceText=e=>e.price?`₹${e.price.toLocaleString('en-IN')}`:'Free';
const pin='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/></svg>';
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function updateCount(){$('#ticketCount').textContent=tickets.length;}
function renderEvents(){
 const query=$('#search').value.trim().toLowerCase();
 let result=events.filter(e=>(category==='All'||e.category===category)&&(!savedOnly||saved.includes(e.id))&&`${e.title} ${e.category} ${e.venue} ${e.city} ${e.description}`.toLowerCase().includes(query));
 const sort=$('#sort').value;result.sort((a,b)=>sort==='featured'?Number(b.featured)-Number(a.featured)||new Date(a.date)-new Date(b.date):sort==='free'?a.price-b.price||new Date(a.date)-new Date(b.date):new Date(a.date)-new Date(b.date));
 $('#resultCount').textContent=`${result.length} experience${result.length===1?'':'s'} to look forward to`;
 $('#emptyState').hidden=result.length>0;
 $('#eventGrid').innerHTML=result.map((e,i)=>`<article class="event-card" style="--i:${i}"><div class="card-image"><img src="${e.image}" alt="${e.alt}" loading="lazy"><div class="card-tags"><span class="tag">${e.category}</span>${e.featured?'<span class="tag featured-tag">↗ Featured</span>':''}</div><button class="save-button" data-save="${e.id}" aria-label="${saved.includes(e.id)?'Unsave':'Save'} ${e.title}" aria-pressed="${saved.includes(e.id)}">${saved.includes(e.id)?'♥':'♡'}</button></div><div class="card-body"><div class="card-date">${dateText(e)} <span>·</span> ${timeFormat.format(new Date(e.date))} IST</div><h3><button class="event-title" data-detail="${e.id}">${e.title}</button></h3><div class="venue">${pin}${e.venue}, ${e.city}</div><p class="card-description">${e.description}</p><div class="card-bottom"><span class="price">${priceText(e)}<small>${e.price?' / person':' entry'}</small></span><button class="event-link" data-detail="${e.id}" aria-label="View ${e.title}">View event <span>↗</span></button></div></div></article>`).join('');
}
function openDialog(id){const dialog=$(id);if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');}
function closeDialog(dialog){dialog.close();if(!$$('dialog[open]').length)document.body.classList.remove('modal-open');}
function openDetails(id){const e=events.find(e=>e.id===id);if(!e)return;selectedEvent=e;$('#eventDetails').innerHTML=`<img class="detail-image" src="${e.image}" alt="${e.alt}"><div class="detail-content"><span class="tag featured-tag">${e.category}</span><h2>${e.title}</h2><div class="detail-meta"><div><small>When</small>${dateText(e)}<br>${timeFormat.format(new Date(e.date))} – ${timeFormat.format(new Date(e.end))} IST</div><div><small>Where</small>${e.venue}<br>${e.city}, India</div><div><small>Your spot</small>${priceText(e)}${e.price?' / person':''}</div><div><small>Hosted by</small>${e.host}</div></div><div class="countdown" id="countdown" aria-live="off"></div><h3>A little about the experience</h3><p class="detail-description">${e.detail}</p><h3>What to expect</h3><ul>${e.includes.map(s=>`<li>${s}</li>`).join('')}</ul><button class="button button-dark detail-register" id="openRegistration">${tickets.some(t=>t.eventId===e.id)?'View my ticket':'Save my spot'} <span>↗</span></button><p class="form-note">Demo event. No payment is collected and no real booking is made.</p></div>`;updateCountdown();openDialog('#eventDialog');}
function updateCountdown(){const el=$('#countdown');if(!el||!selectedEvent)return;const diff=new Date(selectedEvent.date)-Date.now();if(diff<=0){el.textContent=Date.now()<new Date(selectedEvent.end)?'✳ Happening now':'This experience has ended.';return;}const days=Math.floor(diff/86400000),hours=Math.floor(diff/3600000)%24,minutes=Math.floor(diff/60000)%60;el.textContent=`✳ The good times start in ${days}d ${hours}h ${minutes}m`;}
setInterval(updateCountdown,60000);
function openRegistration(){if(!selectedEvent)return;if(tickets.some(t=>t.eventId===selectedEvent.id)){closeDialog($('#eventDialog'));showTickets();return;}if(new Date(selectedEvent.date)<=new Date()){toast('Registration for this experience has closed.');return;}closeDialog($('#eventDialog'));$('#registrationContent').innerHTML=`<div class="eyebrow">YOU’RE ONE STEP AWAY</div><h2>Make it <span class="serif">a plan.</span></h2><p class="dialog-intro">A new experience. A few new faces. A spot with your name on it.</p><form id="registrationForm" novalidate><div class="form-field"><label for="participantName">Full name</label><input id="participantName" name="name" autocomplete="name" placeholder="e.g. Arpit Verma" required maxlength="80" aria-describedby="nameError"><span id="nameError" class="error"></span></div><div class="form-field"><label for="participantEmail">Email address</label><input id="participantEmail" name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="150" aria-describedby="emailError"><span id="emailError" class="error"></span></div><div class="form-field"><label for="participantPhone">Phone number</label><input id="participantPhone" name="phone" type="tel" autocomplete="tel" placeholder="e.g. +91 98765 43210" required maxlength="22" aria-describedby="phoneError"><span id="phoneError" class="error"></span></div><div class="form-field"><label for="selectedEvent">Your experience</label><select id="selectedEvent" name="eventId">${events.filter(e=>new Date(e.date)>new Date()).map(e=>`<option value="${e.id}" ${e.id===selectedEvent.id?'selected':''}>${e.title} — ${dateText(e)}</option>`).join('')}</select></div><p class="form-note">This is a demo registration. Details are saved only on this device. No payment, email or SMS. <button type="button" id="formPrivacy">How we use your data</button></p><button class="button button-dark form-submit" type="submit">Confirm my spot <span>↗</span></button></form>`;openDialog('#registerDialog');$('#registrationForm').addEventListener('submit',submitRegistration);$('#formPrivacy').onclick=()=>openDialog('#privacyDialog');$$('input',$('#registrationForm')).forEach(input=>input.addEventListener('input',()=>{input.removeAttribute('aria-invalid');$(`#${input.name}Error`).textContent='';}));}
function submitRegistration(ev){ev.preventDefault();const form=ev.currentTarget;const data=Object.fromEntries(new FormData(form));data.name=data.name.trim().replace(/\s+/g,' ');data.email=data.email.trim().toLowerCase();data.phone=data.phone.trim();const errors={};if(data.name.length<2||!/[\p{L}]/u.test(data.name))errors.name='Please enter your name (at least 2 characters).';if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(data.email)||!form.elements.email.validity.valid)errors.email='Please enter a valid email address.';const digits=data.phone.replace(/\D/g,'');if(!/^\+?[\d\s().-]+$/.test(data.phone)||digits.length<10||digits.length>15||/^(\d)\1+$/.test(digits))errors.phone='Enter a valid 10–15 digit phone number.';let first=null;for(const field of ['name','email','phone']){const input=form.elements[field];input.setAttribute('aria-invalid',!!errors[field]);$(`#${field}Error`).textContent=errors[field]||'';if(errors[field]&&!first)first=input;}if(first){first.focus();return;}const e=events.find(e=>e.id===data.eventId);if(!e||new Date(e.date)<=new Date()){toast('This event is no longer accepting registrations.');return;}if(tickets.some(t=>t.eventId===data.eventId)){toast('You already have a ticket for this experience.');closeDialog($('#registerDialog'));showTickets();return;}const ticket={...data,code:'GTH-'+Array.from(crypto.getRandomValues(new Uint8Array(6)),v=>v.toString(16).padStart(2,'0')).join('').toUpperCase(),createdAt:new Date().toISOString()};tickets.push(ticket);const persisted=storage.write('gather-tickets',tickets);updateCount();$('#registrationContent').innerHTML=`<div class="success"><div class="success-icon">✓</div><div class="eyebrow" style="justify-content:center">GOOD PLANS LOOK GOOD ON YOU</div><h2>You’re <span class="serif">on the list.</span></h2><p>${escapeHtml(data.name)}, your demo spot for <strong>${e.title}</strong> is confirmed.</p><p>${dateText(e)} · ${timeFormat.format(new Date(e.date))} IST<br>${e.venue}, ${e.city}</p><div class="confirmation-code">${ticket.code}</div><p>${persisted?'Your ticket is saved on this device.':'Your ticket is available for this session. Browser storage is unavailable.'} No email will be sent.</p><button class="button button-dark" id="viewTickets">View my tickets <span>↗</span></button></div>`;$('#viewTickets').onclick=()=>{closeDialog($('#registerDialog'));showTickets();};}
function showTickets(){$('#ticketsList').innerHTML=tickets.length?tickets.map(t=>{const e=events.find(e=>e.id===t.eventId);return `<article class="ticket"><span class="tag featured-tag">DEMO TICKET</span><h3>${e.title}</h3><p>${dateText(e)} · ${timeFormat.format(new Date(e.date))} IST<br>${e.venue}, ${e.city}</p><small>Reserved for ${escapeHtml(t.name)}</small><div class="ticket-code">${escapeHtml(t.code)}</div><div class="ticket-actions"><button data-calendar="${escapeHtml(t.code)}">Add to calendar ↗</button><button data-cancel="${escapeHtml(t.code)}">Cancel registration</button></div></article>`;}).join(''):'<div class="empty-state"><h3>Your next chapter is unwritten.</h3><p>Find an experience you love and save your spot.</p><button class="button button-dark" id="browseFromTickets">Explore events ↗</button></div>';openDialog('#ticketsDialog');$('#browseFromTickets')?.addEventListener('click',()=>{closeDialog($('#ticketsDialog'));$('#events').scrollIntoView({behavior:'smooth'});});}
function downloadCalendar(code){const ticket=tickets.find(t=>t.code===code);if(!ticket)return;const e=events.find(e=>e.id===ticket.eventId);const stamp=s=>new Date(s).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const icsEscape=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,');const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Gather//Demo Events//EN','BEGIN:VEVENT',`UID:${ticket.code}@gather.local`,`DTSTAMP:${stamp(new Date())}`,`DTSTART:${stamp(e.date)}`,`DTEND:${stamp(e.end)}`,`SUMMARY:${icsEscape(e.title+' (Demo event)')}`,`LOCATION:${icsEscape(e.venue+', '+e.city)}`,'DESCRIPTION:Fictional student demo event. This is not a real reservation.','END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([ics],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`gather-${e.id}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$$('dialog').forEach(dialog=>{dialog.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeDialog(dialog);else if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(dialog);}});dialog.addEventListener('close',()=>{if(!$$('dialog[open]').length)document.body.classList.remove('modal-open');});});
document.addEventListener('click',ev=>{const save=ev.target.closest('[data-save]'),detail=ev.target.closest('[data-detail]'),cancel=ev.target.closest('[data-cancel]'),calendar=ev.target.closest('[data-calendar]');if(save){const id=save.dataset.save;const isSaved=saved.includes(id);saved=isSaved?saved.filter(x=>x!==id):[...saved,id];storage.write('gather-saved',saved);if(savedOnly)renderEvents();else{save.setAttribute('aria-pressed',!isSaved);save.setAttribute('aria-label',`${isSaved?'Save':'Unsave'} ${events.find(e=>e.id===id).title}`);save.textContent=isSaved?'♡':'♥';}toast(isSaved?'Removed from your saved events':'Saved for a little later.');}if(detail)openDetails(detail.dataset.detail);if(ev.target.closest('#openRegistration'))openRegistration();if(cancel){if(confirm('Cancel this demo registration?')){tickets=tickets.filter(t=>t.code!==cancel.dataset.cancel);storage.write('gather-tickets',tickets);updateCount();showTickets();toast('Registration cancelled.');}}if(calendar)downloadCalendar(calendar.dataset.calendar);});
$$('.filter').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.category;$$('.filter').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});renderEvents();}));
$('#savedFilter').onclick=()=>{savedOnly=!savedOnly;$('#savedFilter').setAttribute('aria-pressed',savedOnly);renderEvents();};
$('#search').addEventListener('input',renderEvents);$('#sort').addEventListener('change',renderEvents);$('#resetFilters').onclick=()=>{category='All';savedOnly=false;$('#search').value='';$('#savedFilter').setAttribute('aria-pressed',false);$$('.filter').forEach(b=>{const active=b.dataset.category==='All';b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});renderEvents();};
$('#ticketsButton').onclick=showTickets;$('#privacyButton').onclick=()=>openDialog('#privacyDialog');$('#clearData').onclick=()=>{if(!confirm('Delete all Gather registrations, saved events and preferences from this browser?'))return;try{['gather-tickets','gather-saved','gather-theme'].forEach(key=>localStorage.removeItem(key));}catch{}tickets=[];saved=[];updateCount();renderEvents();$('#privacyStatus').textContent='Your local Gather data has been deleted.';if($('#ticketsDialog').open)showTickets();toast('Local data cleared.');};
function setTheme(dark){document.body.classList.toggle('dark',dark);$('#themeButton').textContent=dark?'☀':'☾';$('#themeButton').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`);$('meta[name="theme-color"]').content=dark?'#161c18':'#f7f7ef';}
setTheme(storage.read('gather-theme','light')==='dark');$('#themeButton').onclick=()=>{const dark=!document.body.classList.contains('dark');setTheme(dark);storage.write('gather-theme',dark?'dark':'light');};
document.addEventListener('keydown',ev=>{if(ev.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$$('dialog[open]').length){ev.preventDefault();$('#search').focus();$('#events').scrollIntoView({behavior:'smooth'});}});
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.08});$$('.reveal').forEach(el=>observer.observe(el));$('#year').textContent=new Date().getFullYear();updateCount();renderEvents();
